def bf(planet1, planet2):
    # Define the order of planets from closest to farthest from the Sun
    planets = [
        "Mercury", "Venus", "Earth", "Mars", 
        "Jupiter", "Saturn", "Uranus", "Neptune"
    ]

    # Check if both planet names are valid
    if planet1 not in planets or planet2 not in planets:
        return ()

    try:
        index1 = planets.index(planet1)
        index2 = planets.index(planet2)
    except ValueError:
        return ()  # Should already be covered by the check above, but kept for safety

    # Determine which planet is closer to the Sun (smaller index) and which is farther
    if index1 < index2:
        start_index = index1 + 1
        end_index = index2
    else:
        start_index = index2 + 1
        end_index = index1

    # Slice the list to get planets between them, sorted by proximity to Sun (already in order)
    return tuple(planets[start_index:end_index])


# Example tests:
print(bf("Jupiter", "Neptune"))   # ('Saturn', 'Uranus')
print(bf("Earth", "Mercury"))     # ('Venus',)
print(bf("Mercury", "Uranus"))    # ('Venus', 'Earth', 'Mars', 'Jupiter', 'Saturn')
print(bf("Pluto", "Neptune"))     # ()  (invalid planet name)

